questions.modelAnswer:
class Pipeline {
    std::vector<Stage> stages_;
    std::size_t current_ = 0;   // index survives reallocation
    bool hasCurrent_ = false;
public:
    void add(Stage s) { stages_.push_back(std::move(s)); }
    void select(std::size_t i) {
        if (i >= stages_.size()) throw std::out_of_range("stage");
        current_ = i;
        hasCurrent_ = true;
    }
    Stage& current() {
        if (!hasCurrent_) throw std::logic_error("no stage selected");
        return stages_[current_];
    }
};

